/* Tracking backtest page: reads data/bt_*.csv (generated by backtest.py) and draws the page.
   Both accounts (national team actual nt, next-day mirror mr) use money-weighted (IRR) returns, with the
   same formulas as xirr() / period_stats() in backtest.py: holdings at the start count as invested, holdings
   at the end as returned, and each day's trades are cash flows. The returns table always shows three periods
   (full / 2015-2023 / 2024 to date); the P&L and holdings charts have a range picker (default All) that the
   range table follows; the yearly table and the after-signals table do not depend on it. */
(function () {
  const { num, signCls } = kit;
  const t = (k, v) => i18n.t(k, v);
  const $ = (id) => document.getElementById(id);
  const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  const UPDATE_CMD = 'python -m investdiy.ashare_track_national_team_etf';
  const SPLIT = '2024-01-01';  // keep in sync with SPLIT in backtest.py
  const ACCTS = ['nt', 'mr'];
  const PERIODS = ['all', 'pre', 'post'];
  const HORIZONS = [5, 20, 60, 120];
  const EV_GROUPS = ['entry', 'entry_contra', 'entry_trend', 'exit', 'all_days'];
  const name = (k) => t(`bt.name.${k}`);
  const color = (k) => (k === 'bench' ? 'var(--muted-series)' : kit.series()[ACCTS.indexOf(k)]);
  const pct = (v, d = 1) => (isFinite(v) ? (v > 0 ? '+' : v < 0 ? '−' : '') + d3.format(`.${d}f`)(Math.abs(v)) + '%' : '—');
  const pctAbs = (v, d = 1) => (isFinite(v) ? d3.format(`.${d}f`)(v) + '%' : '—');
  const yi = (v, withSign = false) => (isFinite(v) ? kit.yi(v, 0, withSign) : '—');

  let D = null;
  const R = {};
  let evPeriod = 'all';

  /** Money-weighted annual return (%): sum of cf x (1+r)^(-t/252) = 0, t = trading-day index; bisection, NaN if there is no root */
  function xirr(flows) {
    const npv = (r) => d3.sum(flows, ([tt, cf]) => cf * (1 + r) ** (-tt / 252));
    let lo = -0.99, hi = 10;
    if (npv(lo) * npv(hi) > 0) return NaN;
    for (let i = 0; i < 200; i++) {
      const mid = (lo + hi) / 2;
      if (npv(lo) * npv(mid) <= 0) hi = mid; else lo = mid;
    }
    return ((lo + hi) / 2) * 100;
  }

  /** rows[0] is the start (its holdings count as invested), trades in rows[1..] are cash flows, the last row's holdings count as returned */
  function stats(rows, acct) {
    const n = rows.length - 1;
    if (n < 1) return null;
    const V = `${acct}_value`, T = `${acct}_trade`;
    const v0 = rows[0][V], v1 = rows[n][V];
    const flows = [[0, -v0]];
    let buy = 0, sell = 0, cum = 0;
    const pnl = [0];
    for (let i = 1; i <= n; i++) {
      const a = rows[i][T];
      if (a) { flows.push([i, -a]); if (a > 0) buy += a; else sell -= a; }
      cum += a;
      pnl.push(rows[i][V] - v0 - cum);
    }
    flows.push([n, v1]);
    // IRR is meaningless when almost no money moves
    const irr = Math.max(v0, buy) >= 1 ? xirr(flows) : NaN;
    return { irr, pnl, buy, sell, v0, v1, avg: d3.mean(rows, (r) => r[V]), n };
  }
  const benchAnn = (rows) => ((rows[rows.length - 1].bench / rows[0].bench) ** (252 / (rows.length - 1)) - 1) * 100;

  /** Periods: full from day one; 2015-2023 up to the last day before SPLIT; 2024 to date starting from that day */
  function periodRows(p) {
    const k = D.eq.findIndex((r) => r.date >= SPLIT);
    if (p === 'pre') return D.eq.slice(0, k);
    if (p === 'post') return D.eq.slice(k - 1);
    return D.eq;
  }

  // ---------------- summary ----------------
  function drawTake() {
    const S = Object.fromEntries(PERIODS.map((p) => {
      const rows = periodRows(p);
      return [p, { nt: stats(rows, 'nt'), mr: stats(rows, 'mr'), b: benchAnn(rows) }];
    }));
    const f = (p, k) => pct(k === 'b' ? S[p].b : S[p][k].irr, 1);
    $('take-nt').replaceChildren(...i18n.rich('bt.take.nt', {
      all: f('all', 'nt'), pre: f('pre', 'nt'), post: f('post', 'nt'), ball: f('all', 'b'), bpre: f('pre', 'b'), bpost: f('post', 'b'),
    }));
    $('take-mr').replaceChildren(...i18n.rich('bt.take.mr', { all: f('all', 'mr'), pre: f('pre', 'mr'), post: f('post', 'mr') }));
    // show the interpretation only while the data supports it (no outperformance before 2024, outperformance after)
    const holds = S.pre.nt.irr < S.pre.b && S.post.nt.irr > S.post.b;
    $('take-read').textContent = holds ? t('bt.take.read') : '';
    $('asof').textContent = t('common.asof', { d: D.eq[D.eq.length - 1].date });
  }

  const swatch = (k) => { const i = el('i', 'sw'); i.style.background = color(k); return i; };
  const nameCell = (k) => { const td = el('td'); td.append(swatch(k), name(k)); return td; };

  // ---------------- returns by period ----------------
  function drawSummary() {
    const h1 = el('tr'), h2 = el('tr');
    const first = el('th', null, t('bt.sum.acct')); first.rowSpan = 2; h1.append(first);
    PERIODS.forEach((p) => {
      const th = el('th', 'grp', t(`bt.p.${p}`)); th.colSpan = 3; h1.append(th);
      ['irr', 'pnl', 'avg'].forEach((c, i) => h2.append(el('th', i === 0 ? 'grp' : null, t(`bt.sum.${c}`))));
    });
    $('sum-table').tHead.replaceChildren(h1, h2);
    const S = Object.fromEntries(PERIODS.map((p) => [p, periodRows(p)]));
    const body = [...ACCTS, 'bench'].map((k) => {
      const tr = el('tr');
      tr.append(nameCell(k));
      PERIODS.forEach((p) => {
        if (k === 'bench') {
          const v = benchAnn(S[p]);
          tr.append(el('td', ['grp', signCls(v)].filter(Boolean).join(' '), pct(v, 2)), el('td', null, '—'), el('td', null, '—'));
          return;
        }
        const s = stats(S[p], k), pnl = s.pnl[s.pnl.length - 1];
        tr.append(el('td', ['grp', signCls(s.irr)].filter(Boolean).join(' '), pct(s.irr, 2)),
          el('td', signCls(pnl) || null, yi(pnl, true)), el('td', null, yi(s.avg)));
      });
      return tr;
    });
    $('sum-table').tBodies[0].replaceChildren(...body);
  }

  // ---------------- P&L and holdings (follow the range picker) ----------------
  const rangeRows = () => {
    const [s, e] = R.pnl.get();
    return D.eq.filter((r) => r.d >= s && r.d <= e);
  };

  function drawRangeTable(rows) {
    const cols = ['irr', 'pnl', 'buy', 'sell', 'v0', 'v1', 'avg'];
    const head = el('tr');
    head.append(el('th', null, t('bt.sum.acct')));
    cols.forEach((c) => head.append(el('th', null, t(`bt.r.${c}`))));
    $('range-table').tHead.replaceChildren(head);
    if (rows.length < 2) { $('range-table').tBodies[0].replaceChildren(); return; }
    const body = ACCTS.map((k) => {
      const s = stats(rows, k), pnl = s.pnl[s.pnl.length - 1], tr = el('tr');
      tr.append(nameCell(k), el('td', signCls(s.irr) || null, pct(s.irr, 2)), el('td', signCls(pnl) || null, yi(pnl, true)),
        ...[s.buy, s.sell, s.v0, s.v1, s.avg].map((v) => el('td', null, yi(v))));
      return tr;
    });
    const b = el('tr'), v = benchAnn(rows);
    b.append(nameCell('bench'), el('td', signCls(v) || null, pct(v, 2)), ...cols.slice(1).map(() => el('td', null, '—')));
    $('range-table').tBodies[0].replaceChildren(...body, b);
  }

  const xAxis = (svg, x, W, H, m) => svg.append('g').attr('transform', `translate(0,${H - m.b})`)
    .call(d3.axisBottom(x).ticks(Math.max(3, Math.floor(W / 110))).tickFormat(d3.utcFormat('%Y-%m')).tickSizeOuter(0));

  /** One line chart: series = [{k, vals}], tip(i) returns the tooltip lines */
  function lineChart(box, rows, series, H, tip) {
    const tt = kit.tip($('pnl'));
    kit.ready(box);
    const W = Math.max(280, box.clientWidth), m = { t: 10, r: 14, b: 26, l: 62 };
    const x = d3.scaleUtc(d3.extent(rows, (r) => r.d), [m.l, W - m.r]);
    const all = series.flatMap((s) => s.vals);
    const y = d3.scaleLinear([Math.min(0, d3.min(all)), Math.max(0, d3.max(all)) || 1], [H - m.b, m.t]).nice();
    const svg = d3.select(box).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${H}`);
    const ax = xAxis(svg, x, W, H, m);
    const ay = svg.append('g').attr('transform', `translate(${m.l},0)`)
      .call(d3.axisLeft(y).ticks(5).tickFormat(kit.axisYi).tickSize(-(W - m.l - m.r)));
    ay.select('.domain').remove();
    kit.axisStyle(ax, ay);
    svg.append('line').attr('x1', m.l).attr('x2', W - m.r).attr('y1', y(0)).attr('y2', y(0)).style('stroke', 'var(--axis)');
    const split = new Date(SPLIT);
    if (split > rows[0].d && split < rows[rows.length - 1].d) {
      svg.append('line').attr('x1', x(split)).attr('x2', x(split)).attr('y1', m.t).attr('y2', H - m.b)
        .style('stroke', 'var(--fg-muted)').style('stroke-dasharray', '3 3').style('opacity', 0.6);
      svg.append('text').attr('x', x(split) + 4).attr('y', m.t + 10).text(t('bt.split'))
        .style('fill', 'var(--fg-muted)').style('font-size', '11px');
    }
    series.forEach((s) => svg.append('path').datum(s.vals).attr('d', d3.line((v, i) => x(rows[i].d), (v) => y(v)))
      .style('fill', 'none').style('stroke', color(s.k)).style('stroke-width', 2).style('stroke-linejoin', 'round'));
    const rule = svg.append('line').attr('y1', m.t).attr('y2', H - m.b).style('stroke', 'var(--axis)').style('opacity', 0);
    const dots = series.map((s) => svg.append('circle').attr('r', 3.5).style('fill', color(s.k))
      .style('stroke', 'var(--panel)').style('stroke-width', 2).style('opacity', 0));
    const bis = d3.bisector((r) => r.d).center;
    svg.append('rect').attr('x', m.l).attr('y', m.t).attr('width', W - m.l - m.r).attr('height', H - m.t - m.b)
      .style('fill', 'transparent')
      .on('mousemove', (event) => {
        const i = bis(rows, x.invert(d3.pointer(event)[0]));
        rule.attr('x1', x(rows[i].d)).attr('x2', x(rows[i].d)).style('opacity', 1);
        series.forEach((s, j) => dots[j].attr('cx', x(rows[i].d)).attr('cy', y(s.vals[i])).style('opacity', 1));
        tt.show(event, [{ text: rows[i].date }, ...tip(i)]);
      })
      .on('mouseleave', () => { tt.hide(); rule.style('opacity', 0); dots.forEach((d) => d.style('opacity', 0)); });
  }

  function drawPnl() {
    const rows = rangeRows();
    drawRangeTable(rows);
    $('pnl-legend').replaceChildren(...ACCTS.map((k) => { const s = el('span'); const i = el('i', 'line'); i.style.background = color(k); s.append(i, name(k)); return s; }));
    if (rows.length < 2) { kit.fail($('pnl-box')); kit.fail($('hold-box')); return; }
    const S = Object.fromEntries(ACCTS.map((k) => [k, stats(rows, k)]));
    lineChart($('pnl-box'), rows, ACCTS.map((k) => ({ k, vals: S[k].pnl })), 260,
      (i) => ACCTS.map((k) => ({ color: color(k), text: t('bt.tip.pnl', { n: name(k), v: kit.amt(S[k].pnl[i]) }) })));
    lineChart($('hold-box'), rows, ACCTS.map((k) => ({ k, vals: rows.map((r) => r[`${k}_value`]) })), 180,
      (i) => ACCTS.map((k) => ({ color: color(k), text: t('bt.tip.hold', { n: name(k), v: kit.amt(rows[i][`${k}_value`], { sign: false }) }) })));
  }

  // ---------------- year by year ----------------
  function drawYears() {
    const h1 = el('tr'), h2 = el('tr');
    const th0 = el('th', null, t('bt.year.year')); th0.rowSpan = 2;
    const thb = el('th'); thb.rowSpan = 2; thb.append(swatch('bench'), name('bench'));
    h1.append(th0, thb);
    ACCTS.forEach((k) => {
      const th = el('th', 'grp'); th.colSpan = 3; th.append(swatch(k), name(k)); h1.append(th);
      ['ret', 'pnl', 'avg'].forEach((c, i) => h2.append(el('th', i === 0 ? 'grp' : null, t(`bt.year.${c}`))));
    });
    $('year-table').tHead.replaceChildren(h1, h2);
    const byYear = d3.groups(D.eq, (r) => r.date.slice(0, 4));
    let prev = null;
    const body = byYear.map(([y, rs]) => {
      const rows = prev ? [prev, ...rs] : rs;  // the first year starts on day one (initial position)
      prev = rs[rs.length - 1];
      const tr = el('tr');
      const b = (rows[rows.length - 1].bench / rows[0].bench - 1) * 100;
      tr.append(el('td', null, y), el('td', signCls(b) || null, pct(b)));
      ACCTS.forEach((k) => {
        const s = stats(rows, k);
        const ret = s && isFinite(s.irr) ? ((1 + s.irr / 100) ** (s.n / 252) - 1) * 100 : NaN;  // that year's actual return, not annualised
        const pnl = s ? s.pnl[s.pnl.length - 1] : NaN;
        tr.append(el('td', ['grp', signCls(ret)].filter(Boolean).join(' '), pct(ret)),
          el('td', signCls(pnl) || null, yi(pnl, true)), el('td', null, s ? yi(s.avg) : '—'));
      });
      return tr;
    });
    $('year-table').tBodies[0].replaceChildren(...body.reverse());
  }

  // ---------------- after signals ----------------
  function setPeriod(p) {
    evPeriod = p;
    document.querySelectorAll('#ev-period button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.period === p)));
    drawEvents();
  }

  function drawEvents() {
    const head = el('tr');
    head.append(el('th', null, t('bt.ev.group')), el('th', null, t('bt.ev.n')));
    HORIZONS.forEach((h) => head.append(el('th', null, t('bt.ev.h', { h }))));
    $('ev-table').tHead.replaceChildren(head);
    $('ev-table').tBodies[0].replaceChildren(...EV_GROUPS.map((g) => {
      const r = D.events.find((x) => x.period === evPeriod && x.group === g);
      const tr = el('tr');
      const label = el('td', null, t(`bt.ev.g.${g}`));
      if (g.startsWith('entry_')) label.style.paddingLeft = '26px';  // indent the entry-wave subgroups
      tr.append(label, el('td', null, r ? r.n : '—'));
      HORIZONS.forEach((h) => {
        const v = r ? num(r[`ret${h}`]) : NaN;
        tr.append(el('td', signCls(v) || null, isFinite(v) ? `${pct(v, 2)} (${pctAbs(num(r[`win${h}`]), 0)})` : '—'));
      });
      return tr;
    }));
  }

  function drawAll() {
    if (!D) return;
    drawTake();
    drawSummary();
    drawPnl();
    drawYears();
    drawEvents();
  }

  $('take-nt').textContent = t('common.loading');
  kit.sectionNav($('secnav'));
  kit.downloadLinks('data/');

  Promise.all(['bt_equity', 'bt_events'].map((f) => kit.csv(`data/${f}.csv`)))
    .then(([eq, events]) => {
      D = {
        eq: eq.map((r) => {
          const o = { date: r.date, d: new Date(r.date), bench: num(r.bench) };
          ACCTS.forEach((a) => { o[`${a}_value`] = num(r[`${a}_value`]) || 0; o[`${a}_trade`] = num(r[`${a}_trade`]) || 0; });
          return o;
        }),
        events,
      };
      const [dMin, dMax] = d3.extent(D.eq, (r) => r.d);
      R.pnl = kit.rangePicker($('pnl-range'), { min: dMin, max: dMax, initial: 'all', onChange: drawPnl });
      kit.markStale($('stale'), D.eq[D.eq.length - 1].date);
      document.querySelectorAll('#ev-period button').forEach((b) => b.addEventListener('click', () => setPeriod(b.dataset.period)));
      drawAll();
      kit.onRedraw(drawAll);
    }).catch((err) => {
      console.error(err);
      const show = () => { $('take-nt').textContent = t('loadError', { cmd: UPDATE_CMD }); };
      show();
      i18n.onChange(show);
      ['pnl-box', 'hold-box'].forEach((id) => kit.fail($(id)));
    });
})();
